const { createHmac } = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
if (!secret) throw new Error('LENDLOOP_WEBHOOK_SECRET is missing');
function signed(data) {
  const payload = JSON.stringify({ ...data, timestamp: Date.now() });
  return { payload, signature: createHmac('sha256', secret).update(payload).digest('hex') };
}

const { timingSafeEqual } = require('crypto');
const { payload, signature } = $input.first().json.body ?? {};
if (typeof payload !== 'string' || payload.length > 8192 || !/^[a-f0-9]{64}$/.test(signature ?? ''))
  throw new Error('Invalid notification envelope');
const expected = createHmac('sha256', secret).update(payload).digest();
if (!timingSafeEqual(expected, Buffer.from(signature, 'hex'))) throw new Error('Invalid notification signature');
const event = JSON.parse(payload);
if (typeof event.eventId !== 'string') throw new Error('Invalid event ID');
return [{ json: signed({ operation: 'record-notification', id: event.eventId }) }];
